// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // Ensure C is initialized with dummy addresses (must be done before calling newGrantProposal)
        // Use non-zero addresses so init doesn't revert, but keep them arbitrary.
        address vader = address(0x100);
        address usdv = address(0x200);
        address vault = address(0x300);
        // We don't need actual contracts for this property because newGrantProposal doesn't call external functions.
        c.init(vader, usdv, vault);

        // Record pre-state
        uint256 preCount = c.proposalCount();

        // Call the function that differs
        vm.prank(address(this));
        c.newGrantProposal(recipient, amount);

        // Post-state
        uint256 postCount = c.proposalCount();

        // General rule: proposalCount must increase after a call to newGrantProposal.
        // The reference always increments it; the mutant never does, so postCount == preCount for the mutant.
        assertTrue(postCount > preCount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address _vader, address _usdv, address _vault) public {
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() == _vader);
    }
}

